// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsFile 是低库存阈值配置相对仓库根的位置。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值；没配置时回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := readThresholds(thresholdsFile)
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// readThresholds 读取 path 上的阈值配置，返回 仓库 → 阈值。
// 文件不存在、读不出来、或内容不是 JSON 对象时，第二个返回值为 false。
//
// go test 以包目录为工作目录，所以 path 找不到时再相对上一级目录找一次，
// 让从仓库根与 inventory/ 下调用都能读到同一份 config/thresholds.json。
func readThresholds(path string) (map[string]int, bool) {
	for _, candidate := range []string{path, filepath.Join("..", path)} {
		data, err := os.ReadFile(candidate)
		if err != nil {
			continue
		}
		var thresholds map[string]int
		if err := json.Unmarshal(data, &thresholds); err != nil {
			return nil, false
		}
		return thresholds, true
	}
	return nil, false
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

func TestConfiguredWarehouseUsesConfiguredThreshold(t *testing.T) {
	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(\"shanghai\") = %d, 期望 20", got)
	}
}

func TestIsLowStockStrictLessThanConfiguredThreshold(t *testing.T) {
	if !IsLowStock("shanghai", 19) {
		t.Fatal("低于已配置阈值应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于已配置阈值不算低库存（严格小于）")
	}
}

func TestReadThresholdsFallsBackWhenUnreadable(t *testing.T) {
	dir := t.TempDir()

	cases := []struct {
		name string
		body string
	}{
		{"not-json", "{"},
		{"not-object", "[20]"},
	}
	for _, tc := range cases {
		path := filepath.Join(dir, tc.name+".json")
		if err := os.WriteFile(path, []byte(tc.body), 0o600); err != nil {
			t.Fatalf("写测试配置 %s: %v", path, err)
		}
		if _, ok := readThresholds(path); ok {
			t.Fatalf("readThresholds(%s) 应当失败，内容: %s", path, tc.body)
		}
	}

	if _, ok := readThresholds(filepath.Join(dir, "missing.json")); ok {
		t.Fatal("不存在的配置文件应当失败")
	}
}

func TestDefaultLowStockThresholdIsTen(t *testing.T) {
	if DefaultLowStockThreshold != 10 {
		t.Fatalf("DefaultLowStockThreshold = %d, 期望 10", DefaultLowStockThreshold)
	}
}

